#!/usr/bin/env -S bash
# REX11 self-contained source installer: Rust server 0.5.0, Xray v26.3.27 baseline.
# REX_MANAGER_VERSION=11.0.0
# Embedded source package SHA256: 546cf28c0ef12a07c63e0ff659cecee8ef2b10b804b449ef206c1f35eec5f50f
# Bootstrap lines end with comments so a CRLF terminator stays in the comment.
if [ -z "${BASH_VERSION:-}" ]; then exec /bin/bash -- "$0" "$@"; exit 126; fi # REX11 bootstrap
_rex11_source=${BASH_SOURCE[0]} # REX11 bootstrap
if [ ! -f "$_rex11_source" ] || [ ! -r "$_rex11_source" ]; then printf '%s\n' '请先下载完整的 rex11.sh，再执行 bash rex11.sh；不支持从管道读取脚本。' >&2; exit 1; fi # REX11 bootstrap
if LC_ALL=C grep -q "$(printf '\r')$" -- "$_rex11_source"; then # REX11 bootstrap
    umask 077 # REX11 bootstrap
    _rex11_lf_dir=$(mktemp -d "${TMPDIR:-/tmp}/rex11-lf.XXXXXXXX") || exit 1 # REX11 bootstrap
    trap 'rm -rf -- "$_rex11_lf_dir"' EXIT # REX11 bootstrap
    LC_ALL=C sed 's/\r$//' -- "$_rex11_source" > "$_rex11_lf_dir/rex11.sh" || exit 1 # REX11 bootstrap
    chmod 700 "$_rex11_lf_dir/rex11.sh" || exit 1 # REX11 bootstrap
    printf '%s\n' '检测到 CRLF 换行，已使用临时 LF 副本继续；原文件保留。' >&2 # REX11 bootstrap
    if /bin/bash -- "$_rex11_lf_dir/rex11.sh" "$@"; then _rex11_status=0; else _rex11_status=$?; fi # REX11 bootstrap
    exit "$_rex11_status" # REX11 bootstrap
fi # REX11 bootstrap
unset _rex11_source # REX11 bootstrap
set -euo pipefail
umask 077

show_xray_info() {
    command -v python3 >/dev/null || { echo '需要 python3。请先安装 python3，或先执行本脚本的安装模式。' >&2; return 1; }
    python3 - "$@" <<'PY_XRAY_FIELDS'
"""Print only REALITY targets and serverNames, using Xray's own config parser."""
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys

LOCATION_KEYS = (
    "xray.location.config", "XRAY_LOCATION_CONFIG",
    "xray.location.confdir", "XRAY_LOCATION_CONFDIR",
)


def config_flags(argv):
    result = []
    iterator = iter(argv[1:])
    for arg in iterator:
        flag, equal, value = arg.partition("=")
        flag = flag.lstrip("-") if arg.startswith("-") else ""
        if flag in ("c", "config", "confdir", "format"):
            if not equal:
                value = next(iterator, "")
            if flag != "format" and ("://" in value or value in ("stdin:", "-")):
                raise ValueError("nonlocal configuration")
            result.extend(["-" + flag, value])
    return result


def public_fields(document, source):
    results = []
    if not isinstance(document, dict):
        return results
    inbounds = document.get("inbounds", [])
    if not isinstance(inbounds, list):
        return results
    for index, inbound in enumerate(inbounds):
        if not isinstance(inbound, dict):
            continue
        stream = inbound.get("streamSettings")
        if not isinstance(stream, dict):
            continue
        settings = stream.get("realitySettings")
        if not isinstance(settings, dict):
            continue
        # Construct a new object: never print the input dictionary or parser errors.
        row = {"来源": source, "入站序号": index + 1}
        for key in ("target", "dest"):
            value = settings.get(key)
            if isinstance(value, (str, int)) and not isinstance(value, bool):
                row[key] = value
        names = settings.get("serverNames")
        row["serverNames"] = [x for x in names if isinstance(x, str)] if isinstance(names, list) else []
        if "target" in row or "dest" in row or row["serverNames"]:
            results.append(row)
    return results


def dump_config(executable, flags, cwd, environment):
    try:
        result = subprocess.run(
            [str(executable), "run", "-dump", *flags], cwd=cwd, env=environment,
            stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
            timeout=12, check=False,
        )
        if result.returncode != 0:
            return None
        return json.loads(result.stdout)
    except (OSError, subprocess.TimeoutExpired, ValueError):
        return None


def running_configs(proc=Path("/proc")):
    jobs = []
    for entry in sorted(proc.iterdir()):
        if not entry.name.isdigit():
            continue
        try:
            exe_path = os.readlink(entry / "exe").removesuffix(" (deleted)")
            if not Path(exe_path).name.lower().startswith("xray"):
                continue
            argv = (entry / "cmdline").read_bytes().decode(errors="replace").rstrip("\0").split("\0")
            if "-dump" in argv or "-test" in argv:
                continue
            flags = config_flags(argv)
            env = os.environ.copy()
            for key in LOCATION_KEYS:
                env.pop(key, None)
            # Only preserve config-location environment variables, never display them.
            for item in (entry / "environ").read_bytes().split(b"\0"):
                key, separator, value = item.partition(b"=")
                name = os.fsdecode(key)
                if separator and name in LOCATION_KEYS:
                    env[name] = os.fsdecode(value)
            jobs.append((entry / "exe", flags, entry / "cwd", env, "运行中 Xray PID " + entry.name))
        except (OSError, ValueError):
            continue
    return jobs


def collect(explicit_files=()):
    results, failed = [], 0
    jobs = [] if explicit_files else running_configs()
    for exe, flags, cwd, env, source in jobs:
        document = dump_config(exe, flags, cwd, env)
        if document is None:
            failed += 1
        else:
            results.extend(public_fields(document, source))
    if jobs:
        return results, failed, "按运行中进程参数读取当前磁盘配置；不代表已核对进程内存中的配置。"

    executable = next((x for x in (shutil.which("xray"), "/usr/local/bin/xray", "/usr/bin/xray")
                       if x and os.path.isfile(x) and os.access(x, os.X_OK)), None)
    candidates = [Path(x) for x in explicit_files]
    if not candidates:
        for directory in ("/usr/local/etc/xray", "/etc/xray"):
            parent = Path(directory)
            if parent.is_dir():
                candidates.extend(sorted(p for p in parent.iterdir()
                                         if p.suffix in (".json", ".jsonc", ".yaml", ".yml", ".toml")))
    env = os.environ.copy()
    for key in LOCATION_KEYS:
        env.pop(key, None)
    for number, path in enumerate(candidates, 1):
        if not path.is_file():
            failed += 1
            continue
        source = ("指定配置文件 " if explicit_files else "候选配置文件 ") + str(number)
        if executable:
            document = dump_config(executable, ["-config", str(path.resolve())], "/", env)
        else:
            try:
                document = json.loads(path.read_text(encoding="utf-8-sig"))
            except (OSError, ValueError):
                document = None
        if document is None:
            failed += 1
        else:
            results.extend(public_fields(document, source))
    return results, failed, "读取指定或常见路径下的配置文件，未确认它们正在使用。"


def main():
    results, failed, note = collect(sys.argv[1:])
    print(json.dumps({"说明": note, "REALITY": results, "未能解析的配置数": failed},
                     ensure_ascii=False, indent=2))
    if not results:
        print("未识别到 REALITY 目标。可在 --xray-info 后附上实际配置文件的路径；无需粘贴完整配置。")


if __name__ == "__main__":
    main()
PY_XRAY_FIELDS
}

usage() {
    cat <<'INFO'
REX11 · 管理脚本 11.0.0 · Rust 核心源码 0.5.0 — Debian 12/13 x86_64（实验版）
用法：
  bash rex11.sh                         打开交互安装/管理菜单
  bash rex11.sh --install               首次自定义安装节点，按需编译核心
  bash rex11.sh --configure             只修改节点配置，可选择重启
  bash rex11.sh --upgrade-core          内嵌源码版本更高时升级核心，保留配置
  bash rex11.sh --rebuild               同版本重新编译核心，保留配置
  bash rex11.sh --update-manager        更新管理脚本和 rrv，不编译或重启核心
  bash rex11.sh --update-manager-and-defaults  更新管理入口并应用完整默认组（不升级核心）
  bash rex11.sh --defaults-preview      预览全部默认参数（包含26项3F2）
  bash rex11.sh --apply-defaults        一键应用完整默认组；保留节点身份/兼容策略
  bash rex11.sh --versions              分别显示管理脚本、已安装核心和源码版本
  bash rex11.sh --service-nice          单独应用 Nice=-15；运行中服务会重启
  bash rex11.sh --policy-status         查看握手、版本范围、回放与出站策略
  bash rex11.sh --stats                 查看本机连接及 Vision DIRECT/splice 汇总（核心0.5.0）
  bash rex11.sh --client                显示节点信息、VLESS 链接和终端二维码
  bash rex11.sh --status                查看服务状态
  bash rex11.sh --start                 启动/重启，并设置开机自启
  bash rex11.sh --stop                  停止 Rust 服务
  bash rex11.sh --logs                  查看服务日志
  bash rex11.sh --network               仅BBR/FQ、3F2网络参数与恢复
  bash rex11.sh --micro-menu            28项控制中心
  bash rex11.sh --micro-28              --apply-defaults 的兼容别名
  bash rex11.sh --cleanup-menu          设置每日磁盘清理
  bash rex11.sh --cleanup-preview       预览清理范围
  bash rex11.sh --cleanup               立即清理
  bash rex11.sh --host-status           查看主机实际运行值
  bash rex11.sh --host-recover          恢复未完成的主机/网卡事务
  bash rex11.sh --xray-info [配置路径]    只查看 target/dest、serverNames
  bash rex11.sh --verify                只校验内嵌源码包
  bash rex11.sh --help                  查看说明

新装默认 modern 握手；Mihomo 1.19.32 的 chrome 指纹需选择 legacy。
默认不限制客户端版本号；版本范围与握手格式是独立设置。
升级不自动改变旧节点的兼容策略；用菜单 17 查看，用菜单 2 调整。
可以自定义监听端口（含 443）、目标站、SNI、UUID、shortId、私钥和高级参数。
回车保留现有凭据；新装自动生成。新 VPS 无需预装 Xray；读取已有目标站是可选项。
首次安装和修改配置：确认后写入；默认启动并设置开机自启，也可选择暂不启动。
成功安装后输入 rrv 打开菜单。程序/配置应用失败时尝试恢复此前版本。
REX11 管理脚本 11.0.0，Rust 核心 0.5.0；安装、配置、核心升级各自独立。
已有 REX1–REX10：bash rex11.sh --update-manager，然后输入 rrv。
旧核心单独执行 rrv --upgrade-core 升级至 0.5.0；保留现有凭据与配置。
核心升级/重编译不询问节点参数，不重设3F2或清理，不改变开机自启或停止状态。
需要升级后恢复默认调优值：rrv --upgrade-core && rrv --apply-defaults。
完整默认组会覆盖自定义调优值，运行中的服务重启一次；停止与开机自启状态保留。
只更新入口用 --update-manager；更新后统一调优用 --update-manager-and-defaults。
核心升级先编译和验证现有配置，再替换；原来运行的服务此时会短暂重启。
首次编译、下载工具链和依赖需要联网。升级使用新下载脚本内嵌的核心源码。
没有配置线上更新源；反复运行同一脚本不会下载“最新核心”。
首次安装默认Nice=-15、3F2（26项、BBR/FQ）、Rust版第28项可用默认组、每日自动清理。
安装时可选keep保留系统网络值、关闭自动清理，并自定义服务参数。
3F2修改系统级TCP参数；内核缺少BBR或队列无法恢复时会明确报错。
控制中心13/15/25分别独立设置THP、CPU、Nice/OOM/文件数；25及主机默认组会检查systemd加载值。
28项按Rust能力适配：Go专属项不适用；Dnsmasq接管、原127项网络包未移植。
这是Rust实验服务；Debian12/13、XanMod和用户VPS实机仍未验证。
启动支持LF/CRLF换行；误用sh时自动转交Bash。CRLF使用私有临时副本，保留原文件。
请下载完整脚本后运行；不支持curl管道或bash进程替换读取自包含源码包。
核心0.5.0新增统一任务回收、splice/copy统计与安全回退、可分别配置的阶段超时。
统计为进程内累计，重启清零，不开放网络统计接口；rrv --stats 查看。
旧配置无需补字段；建立阶段继承原握手值，写入等待默认30秒，退出宽限默认5秒。
升级请更新管理入口后执行 rrv --upgrade-core；只更新入口不会升级Rust核心。
恢复未完成事务时，只执行 rrv --host-recover；后面不要添加冒号或事务路径。
INFO
}

mode=${1:-menu}
case "$mode" in
    --help|-h) usage; exit 0 ;;
    --xray-info) shift; show_xray_info "$@"; exit 0 ;;
    --host-recover*)
        if [[ $mode != --host-recover || $# -ne 1 ]]; then
            printf '%s\n' '恢复命令不接受事务路径；不要附加冒号或其他内容。' '请单独执行：' '  rrv --host-recover' '也可打开 rrv，选择主菜单 12。本次没有执行恢复。' >&2
            exit 2
        fi
        mode=host-recover
        ;;
    --verify|menu|install|--install|--configure|--upgrade-core|--rebuild|--update-manager|--update-manager-and-defaults|--defaults-preview|--apply-defaults|--versions|--policy-status|--stats|--service-nice|--client|--status|--start|--stop|--logs|--micro-menu|--micro-28|--network|--cleanup-menu|--cleanup|--cleanup-preview|--host-status)
        [[ $# -le 1 ]] || { usage >&2; exit 2; }
        [[ $mode == --verify ]] || mode=${mode#--}
        ;;
    *) usage >&2; exit 2 ;;
esac

if [[ $mode != --verify ]]; then
    [[ ${EUID} -eq 0 ]] || { echo '请使用 root 执行安装。' >&2; exit 1; }
    [[ $(uname -s) == Linux && $(uname -m) == x86_64 ]] || { echo '需要 Linux x86_64。' >&2; exit 1; }
    # shellcheck source=/dev/null
    source /etc/os-release
    [[ ${ID:-} == debian && ( ${VERSION_ID:-} == 12 || ${VERSION_ID:-} == 13 ) ]] || { echo '此安装入口适用于 Debian 12 或 13。' >&2; exit 1; }
    command -v systemctl >/dev/null || { echo '需要 systemd/systemctl。' >&2; exit 1; }
fi

payload_tmp=$(mktemp -d)
trap 'rm -rf -- "$payload_tmp"' EXIT
payload_line=$(awk '/^__REALITY_SOURCE_PAYLOAD__$/ {print NR + 1; exit}' "${BASH_SOURCE[0]}")
[[ $payload_line =~ ^[0-9]+$ ]] || { echo '内嵌源码包缺失，请重新上传完整脚本。' >&2; exit 1; }
tail -n +"$payload_line" "${BASH_SOURCE[0]}" | base64 --decode > "$payload_tmp/source.zip"
if ! printf '%s  %s\n' '546cf28c0ef12a07c63e0ff659cecee8ef2b10b804b449ef206c1f35eec5f50f' "$payload_tmp/source.zip" | sha256sum --check --status; then
    echo '内嵌源码包校验失败，请重新下载并上传完整脚本。' >&2
    exit 1
fi
echo '内嵌源码包校验通过。'
[[ $mode == --verify ]] && exit 0

if ! command -v python3 >/dev/null; then
    apt-get update
    apt-get install -y --no-install-recommends python3
fi
work_base=${REALITY_LAB_WORKDIR:-/root/reality-rust-builds}
[[ $work_base == /* ]] || { echo 'REALITY_LAB_WORKDIR 必须为绝对路径。' >&2; exit 1; }
# Keep the caller's standard input available to input()/getpass in the manager.
# Executing `python3 - <<...` would make every child inherit an exhausted input.
cat > "$payload_tmp/unpack.py" <<'PY_REX11_UNPACK'
#!/usr/bin/env python3
"""Root-owned source extraction; held lock protects extraction and manager execution."""
import fcntl,hashlib,json,os,stat,subprocess,sys,tempfile,zipfile
from pathlib import Path,PurePosixPath

def safe_directory(path):
    for part in reversed((path,*path.parents)):
        if part.exists() or part.is_symlink():
            st=part.lstat()
            if not stat.S_ISDIR(st.st_mode) or st.st_uid != os.geteuid():
                raise ValueError('构建目录包含符号链接、非目录或其他账户拥有的路径')
            if st.st_mode & 0o022 and not st.st_mode & stat.S_ISVTX:
                raise ValueError('构建目录的上级路径可被其他账户写入')
        else:part.mkdir(mode=0o700)

def run(archive,base,release,installer,action):
    base=Path(os.path.abspath(base));safe_directory(base)
    if base.stat().st_mode & 0o022:raise ValueError('构建目录不能由其他账户写入')
    lock=base/'.rex6-source.lock'
    fd=os.open(lock,os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW,0o600)
    try:
        st=os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_uid != os.geteuid() or st.st_mode & 0o022:raise ValueError('构建锁文件不安全')
        try:fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:raise ValueError('另一个 REX11 管理任务正在使用此目录') from None
        build=base/release;safe_directory(build)
        with zipfile.ZipFile(archive) as z:
            names=z.namelist()
            if len(names)!=len(set(names)):raise ValueError('源码包包含重名文件')
            manifest=json.loads(z.read('reality-vision-lab/MANIFEST.sha256.json'))
            expected={'reality-vision-lab/'+v for v in manifest}|{'reality-vision-lab/MANIFEST.sha256.json'}
            if set(names)!=expected or sum(i.file_size for i in z.infolist())>100*1024*1024:raise ValueError('源码包清单或大小无效')
            for info in z.infolist():
                rel=PurePosixPath(info.filename)
                if rel.is_absolute() or '..' in rel.parts or rel.parts[0]!='reality-vision-lab' or stat.S_ISLNK(info.external_attr>>16):raise ValueError('源码包路径无效')
                data=z.read(info)
                if str(rel)!='reality-vision-lab/MANIFEST.sha256.json' and hashlib.sha256(data).hexdigest()!=manifest[str(rel.relative_to('reality-vision-lab'))]:raise ValueError('源码包文件摘要无效')
                out=build/str(rel);safe_directory(out.parent)
                if out.is_symlink() or (out.exists() and not out.is_file()):raise ValueError('已有源码路径不是普通文件')
                mode=0o700 if (info.external_attr>>16)&0o111 else 0o600
                if out.exists() and out.read_bytes()==data:
                    os.chmod(out,mode);continue
                temp_fd,name=tempfile.mkstemp(prefix='.rex6-',dir=out.parent)
                try:
                    with os.fdopen(temp_fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
                    os.chmod(name,mode);os.replace(name,out)
                finally:
                    if os.path.exists(name):os.unlink(name)
        project=build/'reality-vision-lab'
        return subprocess.call([sys.executable,str(project/'scripts/manage.py'),'--project',str(project),'--installer-self',installer,'--action',action])
    finally:os.close(fd)

if __name__=='__main__':
    try:raise SystemExit(run(*sys.argv[1:]))
    except (ValueError,OSError,zipfile.BadZipFile,KeyError):raise SystemExit('源码包解压/路径检查失败；检查私有构建目录权限、并发任务及文件完整性。')
PY_REX11_UNPACK
python3 "$payload_tmp/unpack.py" "$payload_tmp/source.zip" "$work_base" '0.5.0-546cf28c0ef1' "$(realpath -- "${BASH_SOURCE[0]}")" "$mode"
exit 0
